/**
 * html 元素默认事件
 */
export const eventkeys = [
    'onClick', 'onChange', 'onMouseOver', 'onMouseOut', 
    'onKeyDown', 'onKeyUp', 'onKeyPress', 'onSubmit', 
    'onFocus', 'onBlur', 'onLoad', 'onUnload', 'onError', 
    'onScroll', 'onResize', 'onContextMenu', 'onDoubleClick', 
    'onDrag', 'onDragStart', 'onDragEnd', 'onDragEnter', 
    'onDragLeave', 'onDragOver', 'onDrop', 'onInput', 
    'onSelect', 'onCopy', 'onCut', 'onPaste', 
    'onMouseDown', 'onMouseUp', 'onTouchStart', 'onTouchEnd', 
    'onTouchMove', 'onTouchCancel'
];

const eventProps: JSONSchema['properties'] = {
    onClick: {
        format: "function"
    },
    style: {
        type: "object",
        format: "style",
    },
    className: {
        type: "string",
        format: "class"
    },
    children: {
    },
}
export const getEventProps = (key: string): JSONSchema => {
    switch(key){
        case 'img':
            return { type: "object", properties: { ...eventProps, src: { type: "string", format: "image" } }};
        case 'a':
            return { type: "object", properties: { ...eventProps, src: { type: "string" } } }
    }
    return { type: 'object', properties: eventProps };
}


export const htmlModuleList: ModuleItem[] = htmlElements.map((key) => {
    return {
        props: getEventProps(key),
        display: htmlInlineElements.includes(key)? "inline" : "block",
        specialPaths: [],
        key,
        source: moduleSource.html,
        name: key,
        extraInfo: {},
    }
})